changeSet.sql:
CREATE TABLE patient_visit ( id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, created_date TIMESTAMP WITHOUT TIME ZONE, created_by VARCHAR(255), last_modified_date TIMESTAMP WITHOUT TIME ZONE, last_modified_by VARCHAR(255), facility_id BIGINT, person_uuid VARCHAR(255) NOT NULL, visit_start_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, visit_end_date TIMESTAMP WITHOUT TIME ZONE, uuid VARCHAR(255) NOT NULL, archived INTEGER, CONSTRAINT pk_patient_visit PRIMARY KEY (id) );
ALTER TABLE patient_visit ADD CONSTRAINT uc_patient_visit_uuid UNIQUE (uuid);
ALTER TABLE patient_visit ADD CONSTRAINT FK_PATIENT_VISIT_ON_PERSON_UUID FOREIGN KEY (person_uuid) REFERENCES patient_person (uuid);

CREATE TABLE patient_encounter ( id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, created_date TIMESTAMP WITHOUT TIME ZONE, created_by VARCHAR(255), last_modified_date TIMESTAMP WITHOUT TIME ZONE, last_modified_by VARCHAR(255), facility_id BIGINT, encounter_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, person_uuid VARCHAR(255) NOT NULL, uuid VARCHAR(255) NOT NULL, visit_id VARCHAR(255) NOT NULL, service_code VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL, archived INTEGER, CONSTRAINT pk_patient_encounter PRIMARY KEY (id) );
ALTER TABLE patient_encounter ADD CONSTRAINT uc_patient_encounter_uuid UNIQUE (uuid);
ALTER TABLE patient_encounter ADD CONSTRAINT FK_PATIENT_ENCOUNTER_ON_PERSON_UUID FOREIGN KEY (person_uuid) REFERENCES patient_person (uuid);
ALTER TABLE patient_encounter ADD CONSTRAINT FK_PATIENT_ENCOUNTER_ON_VISIT FOREIGN KEY (visit_id) REFERENCES patient_visit (uuid);

CREATE INDEX idx_patient_person_archived
    ON public.patient_person(archived, uuid);

CREATE INDEX idx_biometric_archived_uuid
    ON public.biometric(archived, person_uuid);

CREATE INDEX idx_patient_person_regyear_sex_active
    ON public.patient_person (date_of_registration, sex)
    WHERE archived = 0;
